/// Without automations-define a trigger is not removed (WFL-1520).
#[test]
fn require_definition_authority_example_3() {
    let d: types::Draft = fixture_fx_draft_22();
    let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveTrigger(
        types::TriggerId("on_points".to_string()),
    )];
    assert_eq!(
        require_definition_authority(&d, &changes),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::Unauthorized,
                message: "the change needs the capability automations-define".to_string(),
                evidence: vec![types::Check {
                    rule: "permission:capability:automations-define".to_string(),
                    passed: false,
                    detail: "does not hold automations-define".to_string()
                }],
                missing: None
            }
        )))
    );
}

