/// Without setting-define a setting is not defined.
#[test]
fn require_definition_authority_example_10() {
    let d: types::Draft = fixture_fx_draft_22();
    let changes: Vec<types::SchemaChange> =
        vec![types::SchemaChange::DefineSetting(types::SettingDef {
            id: types::SettingId("mode".to_string()),
            label: "mode".to_string(),
            r#type: types::SettingType("string".to_string()),
            default: types::Value::Str("light".to_string()),
            levels: std::collections::BTreeSet::from([
                types::SettingLevel::Tenant,
                types::SettingLevel::Team,
                types::SettingLevel::Person,
            ]),
            locked_by: None,
        })];
    assert_eq!(
        require_definition_authority(&d, &changes),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::Unauthorized,
                message: "the change needs the capability setting-define".to_string(),
                evidence: vec![types::Check {
                    rule: "permission:capability:setting-define".to_string(),
                    passed: false,
                    detail: "does not hold setting-define".to_string()
                }],
                missing: None
            }
        )))
    );
}

