/// Without ledger-configure the declarations of the ledger are not changed.
#[test]
fn require_definition_authority_example_12() {
    let d: types::Draft = fixture_fx_draft_22();
    let changes: Vec<types::SchemaChange> =
        vec![types::SchemaChange::SetLedgerLimit(types::LedgerLimit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: None,
            floor: None,
            cap: Some(types::LedgerAmount(5)),
            period_cap: None,
            period: None,
            scope: None,
        })];
    assert_eq!(
        require_definition_authority(&d, &changes),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::Unauthorized,
                message: "the change needs the capability ledger-configure".to_string(),
                evidence: vec![types::Check {
                    rule: "permission:capability:ledger-configure".to_string(),
                    passed: false,
                    detail: "does not hold ledger-configure".to_string()
                }],
                missing: None
            }
        )))
    );
}

