/// A publication that is not declared is not cleared.
#[test]
fn apply_meta_change_example_10() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::ClearPublication {
        object: types::ObjectTypeId("note".to_string()),
    };
    assert_eq!(
        apply_meta_change(&schema, &change),
        Err(types::SchemaProblem::Problem(
            "note declares no publication".to_string()
        ))
    );
}

/// A publication is not cleared on an unknown object type.
#[test]
fn apply_meta_change_example_11() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::ClearPublication {
        object: types::ObjectTypeId("tag".to_string()),
    };
    assert_eq!(
        apply_meta_change(&schema, &change),
        Err(types::SchemaProblem::Problem(
            "no object type tag".to_string()
        ))
    );
}

