/// A language field that is not declared is not cleared.
#[test]
fn apply_meta_change_example_15() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::ClearLanguageField {
        object: types::ObjectTypeId("note".to_string()),
    };
    assert_eq!(
        apply_meta_change(&schema, &change),
        Err(types::SchemaProblem::Problem(
            "note declares no language field".to_string()
        ))
    );
}

/// A language field is not cleared on an unknown object type.
#[test]
fn apply_meta_change_example_16() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::ClearLanguageField {
        object: types::ObjectTypeId("tag".to_string()),
    };
    assert_eq!(
        apply_meta_change(&schema, &change),
        Err(types::SchemaProblem::Problem(
            "no object type tag".to_string()
        ))
    );
}

