/// The record of a product that is not installed is not removed.
#[test]
fn apply_meta_change_example_40() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange =
        types::SchemaChange::RemoveProduct(types::ProductId("badges".to_string()));
    assert_eq!(
        apply_meta_change(&schema, &change),
        Err(types::SchemaProblem::Problem(
            "no product badges".to_string()
        ))
    );
}

