/// When the snapshot does not cover the record the condition follows, the answer is InsufficientState naming it, not a hidden field.
#[test]
fn redact_example_10() {
    let t: types::TenantState = fixture_fx_tenant_state_24();
    let coverage: types::Coverage = types::Coverage::Partial(std::collections::BTreeSet::new());
    let principal: types::Principal = types::Principal::Anonymous;
    let now: crate::prelude::Timestamp = crate::prelude::Timestamp(3000);
    let r: types::Record = types::Record {
        id: types::RecordId(2),
        object: types::ObjectTypeId("post".to_string()),
        version: 1,
        created_by: Some(types::PrincipalId("alpha:writer".to_string())),
        created_at: crate::prelude::Timestamp(2000),
        updated_at: crate::prelude::Timestamp(2000),
        fields: std::collections::BTreeMap::from([
            (
                types::FieldId("author".to_string()),
                types::Value::Ref(types::RecordId(1)),
            ),
            (
                types::FieldId("status".to_string()),
                types::Value::Str("published".to_string()),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("B".to_string()),
            ),
        ]),
    };
    assert_eq!(
        redact(& t, & coverage, & principal, now, & r),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::InsufficientState, message :
        "the snapshot does not cover Record { object: ObjectTypeId(\"person\"), id: RecordId(1) }"
        .to_string(), evidence : vec![types::Check { rule : "coverage".to_string(),
        passed : false, detail :
        "Record { object: ObjectTypeId(\"person\"), id: RecordId(1) }".to_string() }],
        missing : Some(types::Need::Record { object : types::ObjectTypeId("person"
        .to_string()), id : types::RecordId(1) }) })))
    );
}

